// Helper: waits on an event indefinitely, tracking how many times it has woken
// and at what simulation time it last woke.
struct watcher_module : public sc_module {
    sc_event& watched;
    sc_time woke_at;
    int wake_count = 0;

    watcher_module(sc_module_name n, sc_event& e)
        : sc_module(n)
        , watched(e)
    {
        SC_THREAD(do_watch);
    }

    void do_watch()
    {
        for (;;) {
            wait(watched);
            woke_at = sc_time_stamp();
            wake_count++;
        }
    }
};

