// ---- triggered() semantics ----

// triggered() is true in the evaluation phase of the immediate notification
// and false in the next evaluation phase.
struct triggered_after_immediate_module : public sc_module {
    sc_event e;
    watcher_module w;

    SC_CTOR(triggered_after_immediate_module)
        : e("e")
        , w("w", e)
    {
        SC_THREAD(do_test);
    }

    void do_test()
    {
        wait(SC_ZERO_TIME);

        e.notify();

        // "Member function triggered shall return the value true if and only
        // if the event has been triggered in the immediately preceding delta
        // notification phase or it has been triggered in the current
        // evaluation phase via an immediate notification." (§5.10.5)
        EXPECT_TRUE(e.triggered());

        wait(SC_ZERO_TIME); // enter a new evaluation phase

        // The immediate notification is now in a prior evaluation phase, not
        // the immediately preceding delta notification phase. §5.10.5 "if and
        // only if" means triggered() must now return false.
        EXPECT_FALSE(e.triggered());
    }
};

