// In a wait(e1 | e2), triggered() identifies which event actually fired:
// the firing event returns true, the non-firing event returns false.
struct or_list_triggered_module : public sc_module {
    sc_event e1;
    sc_event e2;

    SC_CTOR(or_list_triggered_module)
        : e1("e1")
        , e2("e2")
    {
        SC_THREAD(do_test);
    }

    void do_test()
    {
        // Schedule e1 to fire in the next delta cycle, then wait for either.
        e1.notify(SC_ZERO_TIME);

        wait(e1 | e2);

        // "Member function triggered shall return the value true if and only
        // if the event has been triggered in the immediately preceding delta
        // notification phase..." (§5.10.5)
        // e1 fired in that phase; e2 did not.
        EXPECT_TRUE(e1.triggered());
        EXPECT_FALSE(e2.triggered());
    }
};

